    if(it.head){ m.insertAdjacentHTML('beforeend','<div class="rbx-mh">'+T(it.fa,it.en)+(it.hint?'<span class="rbx-tipdot"'+tip(it.hint[0],it.hint[1])+'></span>':'')/* PM 2026-10-30, LX-24: a group heading's ⓘ */+'</div>'); return; }
    var b=document.createElement('button'); b.type='button'; b.className='rbx-mi'+(it.danger?' danger':''); b.setAttribute('role','menuitem');
    b.disabled=!!it.disabled;
    b.innerHTML=(it.icon?ic(it.icon):'')+'<span class="grow">'+T(it.fa,it.en)+(it.hint?'<span class="hint">'+T(it.hint[0],it.hint[1])+'</span>':'')+'</span>';
    b.addEventListener('click', function(e){ e.stopPropagation(); closeMenu(); if(it.fn) it.fn(); });
