  (AMP2?['mex']:[]).concat(['trend','funnel','retention','flows']).concat(AMP2?['table']:[]).forEach(function(t){ items.push({ icon:'chart-line', fa:TYPE[t][0]+(t==='mex'?' · پیشنهادی':''), en:TYPE[t][1]+(t==='mex'?' · Recommended':''), disabled:false, fn:function(){ newReport(t); } }); });
