  if(AMP2) items.push({ icon:'dots-three', fa:'نوع‌های دیگر نمودار', en:'Other chart types', hint:['چسبندگی، چرخه عمر، تحلیل اثر و نوع‌های دیگر','Stickiness, lifecycle, impact analysis and more'], fn:openMoreTypes });
  items.push({sep:1});
