  if(AMP2 && window.RBCohort) items.push({ icon:'users-three', fa:'کوهورت', en:'Cohort', fn:function(){ RBCohort.open(null); } });
  /* «کوهورت» opens the create drawer (PM 2026-11-16, Amplitude «New Cohort»); «کوهورت از فهرست شناسه‌ها» is launched from inside it (PM, 2026-10-25, WS-20a) */
  /* Amplitude's Create menu ends with «Ask AI to create» (walkthrough:52); a roadmap item in Shahin (step 11b) */
  if(AMP2 && window.RBAi){ items.push({sep:1}); items.push({ icon:'sparkle', fa:'ساختن با دستیار', en:'Ask the assistant to create', fn:function(){ RBAi.composer({ mode:'create' }); } }); }
