function deleteBoard(b){
  /* Mixpanel: deleting the original board deletes its reports AND every linked copy elsewhere */
  var own=RB.SAVED.map(function(s,i){ return i; }).filter(function(i){ return META[i].board===b.id; });
  var elsewhere={};
  own.forEach(function(i){ boardsWithReport(i).forEach(function(x){ if(x.id!==b.id) elsewhere[x.id]=x; }); });
  var names=Object.keys(elsewhere).map(function(k){ return T(elsewhere[k].fa,elsewhere[k].en); });
  confirmBox({ fa:'حذف بورد', en:'Delete board', tone:'bad',
    bodyFa:'«'+T(b.fa,b.en)+'» و '+N(own.length)+' گزارشی که اصلشان در این بورد است حذف می‌شوند.'+(names.length?' کپی‌های لینک‌شدهٔ این گزارش‌ها در «'+names.join('»، «')+'» هم حذف خواهند شد.':''),
    bodyEn:'“'+T(b.fa,b.en)+'” and the '+own.length+' reports whose original lives here will be deleted.'+(names.length?' Their linked copies on “'+names.join('”, “')+'” will be deleted too.':''),
    okFa:'حذف', okEn:'Delete',
    fn:function(){
      own.forEach(function(i){ META[i].archived=true; });
      BOARDS.forEach(function(x){ x.rows=x.rows.map(function(r){ return r.filter(function(c){ return !(c.k==='rep' && own.indexOf(c.r)>-1); }); }); });
      BOARDS=BOARDS.filter(function(x){ return x.id!==b.id; });
      BOARDS.forEach(function(x){ if(x.parent===b.id) x.parent=null; });
      S.board=null; setView('home'); toast('بورد حذف شد','Board deleted');
    } });
}
