function placeCard(b,c){
  /* rows hold up to four cards and twelve columns, like both references */
  var last=b.rows[b.rows.length-1];
  var used=last?last.reduce(function(a,x){ return a+(x.w||6); },0):12;
  if(!last || last.length>=4 || used+(c.w||6)>12) b.rows.push([c]); else last.push(c);
  b.updated=0;
}
