  BOARDS.filter(function(b){ return !b.archived && canEditBoard(b); }).forEach(function(b){ var has=boardReports(b).indexOf(i)>-1;
    items.push({ icon:'squares-four', fa:T(b.fa,b.en)+(has?' ✓':''), en:T(b.fa,b.en)+(has?' ✓':''), disabled:has, hint:has?['این گزارش همین حالا در این داشبورد است','This chart is already on this dashboard']:null, fn:function(){ placeCard(b,{ k:'rep', r:i, w:6 }); toast('به «'+b.fa+'» اضافه شد','Added to “'+b.en+'”'); } }); });
  if(window.RBNotebook){
    items.push({ sep:1 },{ head:1, fa:'نوت‌بوک', en:'Notebook' });
    var nh=noNb?['این نوع نمودار را نمی‌شود به نوت‌بوک اضافه کرد','This chart type can’t be added to a notebook']:null;
    items.push({ icon:'plus', fa:'نوت‌بوک تازه', en:'Create a new notebook', disabled:noNb, hint:nh, fn:function(){ var n=RBNotebook.create(); RBNotebook.addChart(n.id, i); toast('نوت‌بوک تازه با این نمودار ساخته شد','New notebook created with this chart'); } });
    NOTEBOOKS.filter(function(n){ return !n.archived && (n.owner==='me' || canEditSp(space(n.space))); }).forEach(function(n){
      items.push({ icon:'notebook', fa:T(n.fa,n.en), en:T(n.fa,n.en), disabled:noNb, hint:nh, fn:function(){ RBNotebook.addChart(n.id, i); toast('به نوت‌بوک «'+n.fa+'» اضافه شد','Added to the notebook “'+n.en+'”'); } }); });
  }
