      function bindPs(){
        bd.querySelectorAll('[data-ps]').forEach(function(x){ x.addEventListener('click', function(){ pick(x); }); });
        var nw=bd.querySelector('[data-psnew]'); if(nw) nw.addEventListener('click', function(){ newSpaceModal({ onCreate:function(sp){
          var box=bd.querySelector('#rbxSvS'); box.innerHTML=spacePickHtml(sp.id,''); bindPs(); pick(box.querySelector('[data-ps="'+sp.id+'"]')); } }); });
      }
      bindPs();
      /* M1 parity: «ذخیره» stays disabled until the chart has a name */
      var nIn=bd.querySelector('#rbxSvN'); setTimeout(function(){ var sb=bd.parentNode&&bd.parentNode.querySelector('.rbx-mfoot .sh-btn.primary'); if(!sb||!nIn) return;
        function v(){ sb.disabled=!nIn.value.trim(); if(nIn.value.trim()) bd.querySelector('#rbxSvE').hidden=true; } nIn.addEventListener('input', v); v(); if(nIn.value) nIn.select(); }, 70);
      bd.querySelectorAll('[data-sva]').forEach(function(x){ x.addEventListener('click', function(){ x.classList.toggle('on'); addTo[x.getAttribute('data-sva')]=x.classList.contains('on'); }); });
      var sw=bd.querySelector('#rbxSvDisc'); if(sw) sw.addEventListener('click', function(){ sw.classList.toggle('on'); sw.setAttribute('aria-pressed',sw.classList.contains('on')); });
      bd._get=function(){ return { name:bd.querySelector('#rbxSvN').value.trim(), board:chosenB, newBoard:(bd.querySelector('#rbxSvNB')||{}).value, space:chosenS, folder:chosenF,
        desc:(bd.querySelector('#rbxSvD')||{}).value||'', addTo:Object.keys(addTo).filter(function(k){ return addTo[k]; }), disc:sw?sw.classList.contains('on'):true, nb:(bd.querySelector('#rbxSvNb')||{}).value||'' }; };
