      if(MX){ var tb=g.board==='__new'?newBoard({ fa:g.newBoard.trim(), en:g.newBoard.trim() }):board(g.board); o.board=tb.id; placeCard(tb,{k:'rep',r:ni,w:6,mode:'chart'}); }
      else g.addTo.forEach(function(id){ var tb=board(id); if(tb && boardReports(tb).indexOf(ni)<0) placeCard(tb,{k:'rep',r:ni,w:6,mode:'chart'}); });
