/* page title + last crumb: «گزارش‌ها» on every library page, «گزارش‌ساز» inside the builder */
function setPageTitle(key){
  var fa=key==='builder'?'گزارش‌ساز':'گزارش‌ها', en=key==='builder'?'Report builder':'Reports';
  var t=document.querySelector('.sh-page-title');
  if(t){ var icn=t.querySelector(':scope > .info-icon'); t.setAttribute('data-fa',fa); t.setAttribute('data-en',en); t.textContent=T(fa,en); if(icn) t.appendChild(icn);
    t.setAttribute('data-tip-fa',NAME_TIPS[key][0]); t.setAttribute('data-tip-en',NAME_TIPS[key][1]); }
  /* the trail's last step names the page you are on, so it never repeats the module («گزارش‌ها / گزارش‌ها») */
  var hf=fa, he=en;
  if(key!=='builder'){
    if(S.view==='spaces'){ hf='همهٔ فضاها'; he='All spaces'; }
    else if(S.view==='space' && S.space){ var sp=space(S.space); hf=sp.fa; he=sp.en; }
    else if(S.view==='board' && board(S.board)){ var bd=board(S.board); hf=bd.fa; he=bd.en; }
    else if(S.view==='create'){ hf='داشبورد جدید'; he='New dashboard'; }
    else if((S.view==='cohort'||S.view==='person'||S.view==='cohorts') && window.RBCohort){ var cc=RBCohort.crumb(S.view); hf=cc[0]; he=cc[1]; }
    else if((S.view==='gallery'||S.view==='template') && window.RBTpl){ var tc=RBTpl.crumb(); hf=tc[0]; he=tc[1]; }
    else if(/^(computations|profiles|groups|predictions)$/.test(S.view) && window.RBUsers){ var uc=RBUsers.crumb(S.view); hf=uc[0]; he=uc[1]; }
    else { hf='همهٔ محتوا'; he='All content'; }
  }
  var h=document.querySelector('.sh-crumbs .here'); if(h){ h.setAttribute('data-fa',hf); h.setAttribute('data-en',he); h.textContent=T(hf,he); }
  document.title=T('شاهین — '+fa,'Shahin — '+en);
}
