function cohortCount(co){
  if(co.frozen!=null) return co.frozen;   /* a static cohort is a fixed list: its size never recomputes */
  var snap=snapQ();
  try{ RB.Q.type='trend'; RB.Q.range=co.range; RB.Q.filters=[]; RB.Q.trend.gran='auto'; RB.Q.trend.activeUnit=''; var ev=RB.evById(co.ev); if(!ev) return 0; var b=RB.seriesR(ev,true); return Math.round((RB.periodUniques?RB.periodUniques(b):RB.sum(b))*co.f); }
  finally{ restoreQ(snap); }
}
