    (window.RBAlerts?'<button class="rbx-item'+(S.view==='alerts'?' on':'')+'" data-nav="alerts" type="button">'+ic('bell')+'<span class="nm">'+T('مدیریت هشدارها','Manage alerts')+'</span></button>'+'<button class="rbx-item'+(S.view==='releases'?' on':'')+'" data-nav="releases" type="button">'+ic('tag')+'<span class="nm">'+T('خط زمانی انتشار','Release timeline')+'</span></button>':'')+'</div>';
  /* Block A (2026-10-24): Recent and Favorites shortcuts (Amplitude global navigation) */
