    '<button class="rbx-seclink'+(S.view==='spaces'?' on':'')+'" data-nav="spaces" type="button"'+(S.view==='spaces'?' aria-current="page"':'')+'>'+T('همه','All')+'</button></div>';
  var list=mySpaces(), openSp=S.view==='space'&&S.space?space(S.space):null;
