function ampFilterRows(rows, sp){
  var cf=S.contentFilter;
  return rows.filter(function(r){
    if(sp && r.space!==sp.id) return false;
    if(S.folder && r.folder!==S.folder) return false;
    if(cf.flag==='archived'){ if(!r.archived) return false; } else if(r.archived) return false;
    if(!sp && cf.space && r.space!==cf.space) return false;
    if(cf.type && r.kind!==cf.type) return false;
    if(cf.editor && r.editor!==cf.editor) return false;
    if(cf.tag && (r.tags||[]).indexOf(cf.tag)<0) return false;
    if(cf.flag==='official' && !r.official) return false;
    if(cf.flag==='ai' && !r.ai) return false;
    if(cf.flag==='tpl' && !r.tpl) return false;
    if(!r.disc && r.owner!=='me') return false;
    var q=sp?(S.spaceQ||''):cf.q;
    if(q){ var hay=(r.fa+' '+r.en).toLowerCase(); if(hay.indexOf(q.toLowerCase())<0) return false; }
    return true;
  }).sort(function(a,b){ return a.updated-b.updated; });
}
