  place();
  function onDoc(e){ if(!pop.contains(e.target)&&!anchor.contains(e.target)) rangePanelClose(); }
  function onKey(e){ if(e.key==='Escape'){ e.stopPropagation(); rangePanelClose(); anchor.focus(); } }
  setTimeout(function(){ document.addEventListener('mousedown', onDoc, true); }, 0); document.addEventListener('keydown', onKey, true); window.addEventListener('resize', place);
  anchor.setAttribute('aria-expanded','true');
